class IsDateToday {

    operator fun invoke(localDate: LocalDate): Boolean {
        val date = Date.from(localDate.atStartOfDay(ZoneId.systemDefault()).toInstant())
        val today = Date.from(LocalDate.now().atStartOfDay(ZoneId.systemDefault()).toInstant())
        return date == today
    }
